"""Objects/Primitives: Blender's basic shapes, generated by Geometry Nodes.

Unlike the primitives in the Add menu, their size and resolution stay editable after they're
dropped: with gizmos in the viewport (arrows for sizes, boxes and dials for resolution) or the
modifier's inputs in Properties. Each one has UVs, a material input and a
Shade Smooth toggle, and rests on the ground like every other Starter object.
"""

import math

from .common import (RADIANS, density_gizmo, generator_object, object_group, palette,
                     radius_gizmo, resolution_gizmo, rest_on_ground, size_gizmo)
from .registry import asset

CATALOG = "Objects/Primitives"

# Edges sharper than this stay sharp when shading smooth, like Shade Auto Smooth.
SMOOTH_ANGLE = 40 * RADIANS


def _finish(tree, name, mesh, uv, smooth_default):
    """Store UVs, shade, assign the material and put the result on the ground."""
    smooth = tree.input("Shade Smooth", "BOOL", smooth_default,
                        description="Smooth the faces, keeping sharp edges sharp")
    material = tree.input("Material", "MATERIAL", palette("Starter Clay"))
    mesh = tree.n("GeometryNodeStoreNamedAttribute", data_type="FLOAT2", domain="CORNER",
                  Geometry=mesh, Name="UVMap", Value=uv).outputs[0]
    edge_angle = tree.n("GeometryNodeInputMeshEdgeAngle")
    sharp = tree.compare("GREATER_THAN", tree.out(edge_angle, "Unsigned Angle"), SMOOTH_ANGLE)
    mesh = tree.n("GeometryNodeSetShadeSmooth", Geometry=mesh, domain="FACE",
                  Shade_Smooth=smooth).outputs[0]
    mesh = tree.n("GeometryNodeSetShadeSmooth", Geometry=mesh, domain="EDGE",
                  Selection=sharp, Shade_Smooth=False).outputs[0]
    mesh = tree.material(mesh, material)
    tree.output(rest_on_ground(tree, mesh))
    return generator_object(name, tree)


def _size(tree, name="Size", default=1.0, description=""):
    return tree.input(name, "FLOAT", default, min=0.001, subtype="DISTANCE",
                      description=description)


def _top(tree, height):
    return tree.xyz(0.0, 0.0, tree.math("MULTIPLY", height, 0.5))


def _height_gizmo(tree, height):
    """Drags the top of a shape centered on Z, which once on the ground moves the whole change."""
    size_gizmo(tree, height, "Z", origin=tree.xyz(0.0, 0.0, tree.math("MULTIPLY", height, -0.5)),
               centered=False)


def _count(tree, name, default, low, high, description=""):
    return tree.input(name, "INT", default, min=low, max=high, description=description)


@asset("Plane", "object", CATALOG,
       "A flat square on the ground, with subdivisions you can change at any time.",
       ("plane", "primitive", "floor", "square", "flat", "basic"), preview_view="top")
def plane():
    tree = object_group("Plane")
    size_x = _size(tree, "Size X", 2.0)
    size_y = _size(tree, "Size Y", 2.0)
    cuts = _count(tree, "Subdivisions", 1, 1, 1000, "Faces along each side")
    node = tree.n("GeometryNodeMeshGrid", Size_X=size_x, Size_Y=size_y,
                  Vertices_X=tree.math("ADD", cuts, 1.0), Vertices_Y=tree.math("ADD", cuts, 1.0))
    size_gizmo(tree, size_x, "X")
    size_gizmo(tree, size_y, "Y")
    density_gizmo(tree, cuts, size_x, "-X")
    return _finish(tree, "Plane", tree.out(node, "Mesh"), tree.out(node, "UV Map"), False)


@asset("Grid", "object", CATALOG,
       "A finely subdivided flat grid, ready for displacement, sculpting or cloth.",
       ("grid", "primitive", "plane", "subdivided", "displace", "basic"), preview_view="top")
def grid():
    tree = object_group("Grid")
    size_x = _size(tree, "Size X", 2.0)
    size_y = _size(tree, "Size Y", 2.0)
    columns = _count(tree, "Vertices X", 32, 2, 1000)
    rows = _count(tree, "Vertices Y", 32, 2, 1000)
    node = tree.n("GeometryNodeMeshGrid", Size_X=size_x, Size_Y=size_y,
                  Vertices_X=columns, Vertices_Y=rows)
    size_gizmo(tree, size_x, "X")
    size_gizmo(tree, size_y, "Y")
    density_gizmo(tree, columns, size_x, "-X")
    density_gizmo(tree, rows, size_y, "-Y")
    return _finish(tree, "Grid", tree.out(node, "Mesh"), tree.out(node, "UV Map"), False)


@asset("Cube", "object", CATALOG,
       "A box whose width, depth, height and subdivisions stay editable after you drop it.",
       ("cube", "box", "primitive", "block", "basic"))
def cube():
    tree = object_group("Cube")
    size = tree.input("Size", "VECTOR", (1.0, 1.0, 1.0), min=0.001, subtype="TRANSLATION")
    cuts = _count(tree, "Subdivisions", 1, 1, 500, "Faces along each edge")
    vertices = tree.math("ADD", cuts, 1.0)
    node = tree.n("GeometryNodeMeshCube", Size=size, Vertices_X=vertices, Vertices_Y=vertices,
                  Vertices_Z=vertices)
    x, y, z = tree.separate(size)
    size_gizmo(tree, x, "X")
    size_gizmo(tree, y, "Y")
    _height_gizmo(tree, z)
    density_gizmo(tree, cuts, x, "-X")
    return _finish(tree, "Cube", tree.out(node, "Mesh"), tree.out(node, "UV Map"), False)


@asset("UV Sphere", "object", CATALOG,
       "A sphere made of rings and segments, with a radius and resolution you can change.",
       ("sphere", "ball", "uv sphere", "primitive", "round", "basic"))
def uv_sphere():
    tree = object_group("UV Sphere")
    radius = _size(tree, "Radius", 0.5)
    segments = _count(tree, "Segments", 32, 3, 1024, "Vertices around the equator")
    rings = _count(tree, "Rings", 16, 2, 1024, "Bands from pole to pole")
    node = tree.n("GeometryNodeMeshUVSphere", Segments=segments, Rings=rings, Radius=radius)
    radius_gizmo(tree, radius)
    resolution_gizmo(tree, segments, tree.xyz(0.0, 0.0, radius), per_turn=32.0)
    density_gizmo(tree, rings, tree.math("MULTIPLY", radius, 2.0), "-Y")
    return _finish(tree, "UV Sphere", tree.out(node, "Mesh"), tree.out(node, "UV Map"), True)


@asset("Ico Sphere", "object", CATALOG,
       "A sphere made of even triangles, with no poles, which sculpts and deforms evenly.",
       ("sphere", "icosphere", "ico", "primitive", "triangles", "basic"))
def ico_sphere():
    tree = object_group("Ico Sphere")
    radius = _size(tree, "Radius", 0.5)
    level = _count(tree, "Subdivisions", 3, 1, 7, "Each level has four times the faces")
    node = tree.n("GeometryNodeMeshIcoSphere", Radius=radius, Subdivisions=level)
    radius_gizmo(tree, radius)
    resolution_gizmo(tree, level, tree.xyz(0.0, 0.0, radius), per_turn=6.0)
    return _finish(tree, "Ico Sphere", tree.out(node, "Mesh"), tree.out(node, "UV Map"), True)


@asset("Cylinder", "object", CATALOG,
       "A round column with flat caps, with editable radius, height and resolution.",
       ("cylinder", "column", "tube", "primitive", "round", "basic"))
def cylinder():
    tree = object_group("Cylinder")
    radius = _size(tree, "Radius", 0.5)
    height = _size(tree, "Height", 1.0)
    vertices = _count(tree, "Vertices", 32, 3, 512, "Vertices around the side")
    rings = _count(tree, "Side Segments", 1, 1, 512, "Rings along the height")
    node = tree.n("GeometryNodeMeshCylinder", fill_type="NGON", Vertices=vertices,
                  Side_Segments=rings, Radius=radius, Depth=height)
    radius_gizmo(tree, radius)
    _height_gizmo(tree, height)
    resolution_gizmo(tree, vertices, _top(tree, height), per_turn=32.0)
    density_gizmo(tree, rings, height, "-Y", color="SECONDARY")
    return _finish(tree, "Cylinder", tree.out(node, "Mesh"), tree.out(node, "UV Map"), True)


@asset("Cone", "object", CATALOG,
       "A cone, or a truncated cone when the top radius is above zero.",
       ("cone", "pyramid", "primitive", "taper", "basic"))
def cone():
    tree = object_group("Cone")
    bottom = _size(tree, "Radius Bottom", 0.5)
    top = tree.input("Radius Top", "FLOAT", 0.0, min=0.0, subtype="DISTANCE")
    height = _size(tree, "Height", 1.0)
    vertices = _count(tree, "Vertices", 32, 3, 512, "Vertices around the side")
    node = tree.n("GeometryNodeMeshCone", fill_type="NGON", Vertices=vertices,
                  Radius_Top=top, Radius_Bottom=bottom, Depth=height)
    radius_gizmo(tree, bottom, origin=tree.xyz(0.0, 0.0, tree.math("MULTIPLY", height, -0.5)))
    radius_gizmo(tree, top, origin=_top(tree, height))
    _height_gizmo(tree, height)
    resolution_gizmo(tree, vertices, tree.xyz(0.0, 0.0, 0.0), per_turn=32.0)
    return _finish(tree, "Cone", tree.out(node, "Mesh"), tree.out(node, "UV Map"), True)


@asset("Torus", "object", CATALOG,
       "A ring with a round cross section, with editable radii and resolution.",
       ("torus", "donut", "ring", "primitive", "round", "basic"))
def torus():
    tree = object_group("Torus")
    major = _size(tree, "Major Radius", 0.4, "Distance from the center to the middle of the tube")
    minor = _size(tree, "Minor Radius", 0.12, "Radius of the tube")
    major_segments = _count(tree, "Major Segments", 48, 3, 1024, "Segments around the ring")
    minor_segments = _count(tree, "Minor Segments", 16, 3, 1024, "Segments around the tube")
    # A grid wrapped twice: columns go around the ring, rows around the tube. The grid's own UVs
    # unwrap it, with the seams where the grid's edges meet.
    node = tree.n("GeometryNodeMeshGrid", Size_X=1.0, Size_Y=1.0,
                  Vertices_X=tree.math("ADD", major_segments, 1.0),
                  Vertices_Y=tree.math("ADD", minor_segments, 1.0))
    u, v, _ = tree.separate(tree.n("GeometryNodeInputPosition").outputs[0])
    around = tree.math("MULTIPLY", tree.math("ADD", u, 0.5), math.tau)
    tube = tree.math("MULTIPLY", tree.math("ADD", v, 0.5), math.tau)
    r = tree.math("MULTIPLY_ADD", minor, tree.math("COSINE", tube), major)
    position = tree.xyz(tree.math("MULTIPLY", r, tree.math("COSINE", around)),
                        tree.math("MULTIPLY", r, tree.math("SINE", around)),
                        tree.math("MULTIPLY", minor, tree.math("SINE", tube)))
    mesh = tree.n("GeometryNodeSetPosition", Geometry=tree.out(node, "Mesh"),
                  Position=position).outputs[0]
    mesh = tree.n("GeometryNodeMergeByDistance", Geometry=mesh, Distance=1e-5).outputs[0]
    # The ring's radius from its outer edge; the tube's from its top, which rises twice as far
    # once the torus rests on the ground.
    tree.linear_gizmo(tree.math("MULTIPLY", major, 1.0),
                      tree.xyz(tree.math("ADD", major, minor)), (1.0, 0.0, 0.0), color="X")
    tree.linear_gizmo(tree.math("MULTIPLY", minor, 2.0),
                      tree.xyz(tree.math("MULTIPLY", major, -1.0), 0.0, minor), (0.0, 0.0, 1.0),
                      color="Z")
    resolution_gizmo(tree, major_segments, tree.xyz(0.0, 0.0, minor), per_turn=48.0)
    resolution_gizmo(tree, minor_segments, tree.xyz(0.0, tree.math("MULTIPLY", major, -1.0), 0.0),
                     up="Y", per_turn=16.0)
    return _finish(tree, "Torus", mesh, tree.out(node, "UV Map"), True)


@asset("Circle", "object", CATALOG,
       "A flat filled disc on the ground, with an editable radius and number of vertices.",
       ("circle", "disc", "disk", "primitive", "round", "flat", "basic"), preview_view="top")
def circle():
    tree = object_group("Circle")
    radius = _size(tree, "Radius", 0.5)
    vertices = _count(tree, "Vertices", 32, 3, 1024)
    mesh = tree.n("GeometryNodeMeshCircle", fill_type="NGON", Vertices=vertices,
                  Radius=radius).outputs["Mesh"]
    radius_gizmo(tree, radius)
    resolution_gizmo(tree, vertices, tree.xyz(), per_turn=32.0)
    # Project the disc onto UV space, filling the unit square.
    x, y, _ = tree.separate(tree.n("GeometryNodeInputPosition").outputs[0])
    scale = tree.math("DIVIDE", 0.5, radius)
    uv = tree.xyz(tree.math("MULTIPLY_ADD", x, scale, 0.5),
                  tree.math("MULTIPLY_ADD", y, scale, 0.5))
    return _finish(tree, "Circle", mesh, uv, False)
